const NAV=[['Home','home'],['Calendar','calendar'],['Tournaments','tournaments'],['Rankings','rankings'],['Players','players'],['Doubles','doubles'],['Juniors','juniors'],['National Teams','national-teams'],['Magazine','magazine'],['Almanac','almanac'],['Records','records'],['World','world']];
const clone=value=>typeof structuredClone==='function'?structuredClone(value):JSON.parse(JSON.stringify(value));
const routePath=(page,...parts)=>`/${[page,...parts].map(x=>encodeURIComponent(String(x))).join('/')}`;
function parseRoute(){const raw=(window.location.hash||'#/home').replace(/^#\/?/,'');const parts=raw.split('/').filter(Boolean).map(decodeURIComponent);return {page:parts[0]||'home',parts:parts.slice(1)};}
function useHashRoute(){const [route,setRoute]=useState(parseRoute);useEffect(()=>{const h=()=>setRoute(parseRoute());window.addEventListener('hashchange',h);if(!window.location.hash)window.location.hash='#/home';return()=>window.removeEventListener('hashchange',h);},[]);const go=(page,...parts)=>{window.location.hash=`#${routePath(page,...parts)}`;};const back=(fallback='home')=>{if(window.history.length>1)window.history.back();else go(fallback);};return {route,go,back};}
function PlayerLink({player,onOpen,children}){return <button className="player-link" onClick={()=>onOpen(player.id)}>{children||fullName(player)}</button>}
function TopRanking({title,players,onOpen,metric='rankingPoints'}){return <article className="panel ranking-panel"><div className="panel-title"><h3>{title}</h3><span>{metric==='race'?'Current-year race':'Live 52-week table'}</span></div><ol>{players.slice(0,5).map((p,i)=><li key={p.id}><span className="rank-number">{i+1}</span><Flag code={p.country}/><div><PlayerLink player={p} onOpen={onOpen}/><small>{p.rarity} · {p.style}</small></div><strong>{(metric==='race'?p.season.racePoints:p.rankingPoints).toLocaleString()}</strong></li>)}</ol></article>}

const TIER_GROUPS=[
 {key:'Grand Slam',label:'Grand Slams',levels:['Grand Slam']},
 {key:'International',label:'International (Olympics & team cups)',levels:['Olympics','Team','Continental']},
 {key:'1000',label:'Masters / WTA 1000',levels:['1000']},
 {key:'Finals',label:'Tour Finals',levels:['Finals']},
 {key:'500',label:'500 Series',levels:['500']},
 {key:'250',label:'250 Series',levels:['250']},
 {key:'Development',label:'Challenger / WTA 125',levels:['Challenger','WTA 125']},
 {key:'ITF',label:'ITF',levels:['ITF']},
 {key:'Juniors',label:'Junior circuit',levels:['Junior Slam','Junior Finals','Junior 500']},
];
const tierKey=level=>TIER_GROUPS.find(group=>group.levels.includes(level))?.key||level;
function TierMultiSelect({selected,onChange,available}){
 const options=TIER_GROUPS.filter(group=>group.levels.some(level=>available.includes(level)));
 const toggle=key=>onChange(selected.includes(key)?selected.filter(x=>x!==key):[...selected,key]);
 const label=selected.length===0?'All tiers':selected.length===1?(options.find(x=>x.key===selected[0])?.label||selected[0]):`${selected.length} tiers selected`;
 return <details className="multi-select"><summary>{label}</summary><div>{options.map(group=><label key={group.key}><input type="checkbox" checked={selected.includes(group.key)} onChange={()=>toggle(group.key)}/><span>{group.label}</span></label>)}{selected.length>0&&<button type="button" onClick={()=>onChange([])}>Clear · All tiers</button>}</div></details>;
}
function SortHeader({label,sortKey,active,direction,onSort}){return <th><button className={active?'sort-header active':'sort-header'} onClick={()=>onSort(sortKey)}>{label}{active?<span>{direction==='asc'?'▲':'▼'}</span>:null}</button></th>}
function no1Reigns(universe,tour){
 const byWeek=new Map();for(const snapshot of universe.rankingHistory||[])if(snapshot?.[tour]?.[0])byWeek.set(`${snapshot.year}-${snapshot.week}`,snapshot);
 const ordered=[...byWeek.values()].sort((a,b)=>a.year-b.year||a.week-b.week),reigns=[];
 for(const snapshot of ordered){const leader=snapshot[tour][0],last=reigns.at(-1);if(last&&last.playerId===leader.id){last.weeks+=1;last.maxPoints=Math.max(last.maxPoints,leader.points||0);last.endYear=snapshot.year;last.endWeek=snapshot.week;}else reigns.push({playerId:leader.id,startYear:snapshot.year,startWeek:snapshot.week,endYear:snapshot.year,endWeek:snapshot.week,weeks:1,maxPoints:leader.points||0});}
 return reigns;
}

function HomePage({universe,onPlayer,onTournament}){
 const nextMajor=universe.calendar.find(e=>e.week>=universe.week&&['Grand Slam','Olympics'].includes(e.level));
 const active=universe.calendar.filter(e=>e.week===universe.week&&e.status!=='completed').slice(0,8);
 const latest=[...universe.tournamentEditions].reverse().slice(0,8);
 const latestMajors=[...universe.tournamentEditions].filter(e=>e.event.level==='Grand Slam').reverse().slice(0,8);
 const fatigue=[...universe.players.ATP,...universe.players.WTA].sort((a,b)=>b.fatigue-a.fatigue).slice(0,6);
 const movers=[...universe.players.ATP,...universe.players.WTA].sort((a,b)=>((b.previousRanking||b.ranking)-b.ranking)-((a.previousRanking||a.ranking)-a.ranking)).slice(0,6);
 const currentSurface=active[0]?.surface||universe.calendar.find(e=>e.week>=universe.week)?.surface||'Off-season';
 const records=[...universe.players.ATP,...universe.players.WTA].filter(p=>p.career.majors>0||p.career.longestWinStreak>=10).sort((a,b)=>b.career.majors-a.career.majors||b.career.longestWinStreak-a.career.longestWinStreak).slice(0,5);
 const followed=(universe.followedPlayerIds||[]).map(id=>findPlayer(universe,id)).filter(Boolean);
 return <div className="page home-page"><section className="hero-scoreboard"><div><p className="kicker">{universeWeekLabel(universe,universe.year,universe.week)}</p><h1>The world tour is alive</h1><p>Every draw, ranking, partnership and career is connected to one canonical history.</p></div><div className="next-major"><span>Next landmark</span><strong>{nextMajor?.name||'Season review'}</strong><p>{nextMajor?`In ${Math.max(0,nextMajor.week-universe.week)} weeks · ${nextMajor.surface} · ${nextMajor.location}`:'The final events have been played.'}</p><SurfaceBadge surface={currentSurface}/></div></section>
 <section className="population-strip"><div><strong>{universe.players.ATP.length}</strong><span>ATP singles</span></div><div><strong>{universe.players.WTA.length}</strong><span>WTA singles</span></div><div><strong>{universe.doublesPlayers.ATP.length+universe.doublesPlayers.WTA.length}</strong><span>Doubles specialists</span></div><div><strong>{universe.juniors.ATP.length+universe.juniors.WTA.length}</strong><span>Junior prospects</span></div></section>
 {followed.length>0&&<section className="panel followed-panel"><div className="panel-title"><h3>Followed players</h3><span>Your career watchlist</span></div><div className="followed-grid">{followed.map(p=><button key={p.id} onClick={()=>onPlayer(p.id)}><Flag code={p.country}/><div><strong>{fullName(p)}</strong><small>{p.tour} · {p.status==='retired'?'Retired':p.junior?`Junior No. ${p.juniorRanking}`:p.doublesSpecialist?`Doubles No. ${p.doublesRanking}`:`World No. ${p.ranking}`}</small></div><RarityBadge rarity={p.rarity}/><span>{p.season?.wins||0}-{p.season?.losses||0}</span></button>)}</div></section>}
 <section className="panel"><div className="panel-title"><h3>Current week</h3><span>{currentSurface} swing · active and upcoming draws</span></div><div className="event-card-grid">{active.length?active.map(e=><button key={e.id} onClick={()=>onTournament(tournamentKey(e.tour,e.name))}><span>{e.tour} · {e.level}</span><strong>{e.name}</strong><small>{e.location}</small><SurfaceBadge surface={e.surface}/></button>):<EmptyState>No events remain this week.</EmptyState>}</div></section>
 <section className="two-column"><TopRanking title="ATP Top Five" players={universe.players.ATP} onOpen={onPlayer}/><TopRanking title="WTA Top Five" players={universe.players.WTA} onOpen={onPlayer}/><TopRanking title="ATP Race" players={[...universe.players.ATP].sort((a,b)=>b.season.racePoints-a.season.racePoints)} onOpen={onPlayer} metric="race"/><TopRanking title="WTA Race" players={[...universe.players.WTA].sort((a,b)=>b.season.racePoints-a.season.racePoints)} onOpen={onPlayer} metric="race"/></section>
 <section className="panel"><div className="panel-title"><h3>Latest major winners and defending champions</h3><span>Historical links open the full tournament page</span></div><div className="major-grid">{latestMajors.length?latestMajors.map(e=><button key={e.id} onClick={()=>onTournament(tournamentKey(e.event.tour,e.event.name))}><span>{universeYearLabel(universe,e.event.year)} · {e.event.tour}</span><strong>{e.event.name}</strong><p><Flag code={e.championCountry}/>{e.championName}</p></button>):<EmptyState>The first majors are still ahead.</EmptyState>}</div></section>
 <section className="two-column"><article className="panel"><div className="panel-title"><h3>Latest notable matches</h3><span>Stored match records</span></div>{latest.map(e=>{const m=e.matches?.find(x=>x.round==='F')||e.matches?.at(-1);return m?<button className="home-match" key={e.id} onClick={()=>onTournament(tournamentKey(e.event.tour,e.event.name))}><div><strong>{e.event.name}</strong><small>{e.event.tour} · {e.event.level}</small></div><b>{m.score}</b><span>{e.championName}</span></button>:null})}</article><article className="panel"><div className="panel-title"><h3>Ranking movers</h3><span>Previous week to now</span></div>{movers.map(p=><div className="mover-row" key={p.id}><Flag code={p.country}/><PlayerLink player={p} onOpen={onPlayer}/><Movement player={p}/><strong>No. {p.ranking}</strong></div>)}</article></section>
 <section className="two-column"><article className="panel"><div className="panel-title"><h3>Form and fatigue watch</h3><span>Schedule congestion</span></div>{fatigue.map(p=><div className="fatigue-row" key={p.id}><div><Flag code={p.country}/><PlayerLink player={p} onOpen={onPlayer}/><small>{p.tour} · No. {p.ranking}</small></div><Meter label="Fatigue" value={p.fatigue} compact/></div>)}</article><article className="panel"><div className="panel-title"><h3>Record watch</h3><span>Active historical chases</span></div>{records.map(p=><button className="leader-row" key={p.id} onClick={()=>onPlayer(p.id)}><Flag code={p.country}/><strong>{fullName(p)}</strong><span>{p.career.majors} majors</span><b>{p.career.longestWinStreak} streak</b></button>)}</article></section>
 <section className="panel magazine-preview"><div className="panel-title"><h3>Latest Chronicle</h3><span>Why the week mattered</span></div>{universe.magazine.slice(0,8).map(story=><article key={story.id}><span>{story.category}</span><h4>{replaceCalendarYears(universe,story.headline)}</h4><p>{replaceCalendarYears(universe,story.body)}</p></article>)}</section></div>;
}

function CalendarPage({universe,tour,onTournament}){
 const [tiers,setTiers]=useState([]);const available=[...new Set(universe.calendar.filter(e=>e.tour===tour).map(e=>e.level))];
 const events=universe.calendar.filter(e=>e.tour===tour&&(tiers.length===0||tiers.includes(tierKey(e.level))));const weeks=[...new Set(events.map(e=>e.week))];
 return <div className="page"><SectionTitle eyebrow={`${tour} world tour`}>Annual calendar</SectionTitle><div className="filter-row"><TierMultiSelect selected={tiers} onChange={setTiers} available={available}/></div><div className="calendar-list">{weeks.map(week=><section className={`calendar-week ${week===universe.week?'current':''}`} key={week}><div className="week-marker"><span>WEEK</span><strong>{week}</strong></div><div className="calendar-events">{events.filter(e=>e.week===week).map(e=><button key={e.id} onClick={()=>onTournament(tournamentKey(tour,e.name))}><div><h3>{e.name}</h3><p>{e.location} · {e.level}</p></div><SurfaceBadge surface={e.surface}/><span className={`status ${e.status}`}>{e.status}</span></button>)}</div></section>)}</div></div>
}


function TournamentsPage({universe,tour,onTournament}){
 const [tiers,setTiers]=useState([]),[type,setType]=useState('All');const rows=new Map();
 for(const e of universe.calendar.filter(e=>e.tour===tour)){const eventType=e.level==='Team'?'Team':'Singles';rows.set(`${eventType.toLowerCase()}-${e.name}`,{type:eventType,event:e,editions:universe.tournamentEditions.filter(x=>x.event.tour===tour&&x.event.name===e.name)});}
 for(const e of universe.juniorCalendar.filter(e=>e.tour===tour))rows.set(`junior-${e.name}`,{type:'Junior',event:e,editions:universe.juniorEditions.filter(x=>x.event.tour===tour&&x.event.name===e.name)});
 for(const e of universe.calendar.filter(e=>e.tour===tour&&['Grand Slam','Olympics','Finals','1000','500','250'].includes(e.level))){const name=`${e.name} Doubles`;rows.set(`doubles-${name}`,{type:'Doubles',event:{...e,name,drawSize:e.level==='Grand Slam'?64:e.level==='Olympics'?32:e.level==='1000'?32:e.level==='500'?16:8},editions:universe.doublesEditions.filter(x=>x.event.tour===tour&&x.event.name===name)});}
 const allRows=[...rows.values()],available=[...new Set(allRows.map(r=>r.event.level))];
 const list=allRows.filter(r=>(tiers.length===0||tiers.includes(tierKey(r.event.level)))&&(type==='All'||r.type===type)).sort((a,b)=>{const pa=TIER_GROUPS.findIndex(g=>g.key===tierKey(a.event.level)),pb=TIER_GROUPS.findIndex(g=>g.key===tierKey(b.event.level));return pa-pb||a.event.week-b.event.week||a.type.localeCompare(b.type)});
 return <div className="page"><SectionTitle eyebrow={`${tour} tournament browser`}>Tournaments</SectionTitle><div className="filter-row"><select value={type} onChange={e=>setType(e.target.value)}><option value="All">All tournament types</option>{['Singles','Doubles','Junior','Team'].map(x=><option key={x}>{x}</option>)}</select><TierMultiSelect selected={tiers} onChange={setTiers} available={available}/></div><div className="tournament-card-grid">{list.map(row=>{const latest=[...row.editions].sort((a,b)=>b.event.year-a.event.year)[0],champion=row.type==='Doubles'?latest?.championNames?.join(' / '):row.type==='Team'&&latest?.championCountry?countryByCode(latest.championCountry).name:latest?.championName;return <button key={`${row.type}-${row.event.name}`} onClick={()=>onTournament(tournamentKey(tour,row.event.name))}><header><span>Week {row.event.week} · {row.type}</span><SurfaceBadge surface={row.event.surface}/></header><h3>{row.event.name}</h3><p>{row.event.location} · {row.event.level}</p><div><strong>{champion||'Upcoming'}</strong><small>{latest?`${universeYearLabel(universe,latest.event.year)} champion${row.type==='Doubles'?'s':''}`:`${row.event.drawSize}-entry draw`}</small></div></button>})}</div></div>;
}


function RankingsPage({universe,tour,onPlayer,search}){
 const [view,setView]=useState('Current status'),[status,setStatus]=useState('Current'),[nation,setNation]=useState('All'),[surface,setSurface]=useState('All'),[age,setAge]=useState('All'),[rarity,setRarity]=useState('All'),[careerStatus,setCareerStatus]=useState('Active'),[sort,setSort]=useState({key:'rank',direction:'asc'});
 const snapshots=universe.rankingHistory.filter(s=>s[tour]?.length).slice(-1040).reverse();let rows;
 if(status==='Current'){const source=careerStatus==='Retired'?universe.retiredPlayers[tour]:careerStatus==='All'?[...universe.players[tour],...universe.retiredPlayers[tour]]:universe.players[tour];rows=source.map(p=>({p,rank:p.ranking,points:p.rankingPoints||0,race:p.season?.racePoints||0}));}
 else{const [year,week]=status.split('-').map(Number),snap=snapshots.find(s=>s.year===year&&s.week===week);rows=(snap?.[tour]||[]).map(r=>({p:findPlayer(universe,r.id),rank:r.rank,points:r.points,race:r.racePoints||0})).filter(r=>r.p&&(careerStatus==='All'||(careerStatus==='Active'&&r.p.status!=='retired')||(careerStatus==='Retired'&&r.p.status==='retired')));}
 rows=rows.filter(({p})=>(nation==='All'||p.country===nation)&&(rarity==='All'||p.rarity===rarity)&&(age==='All'||(age==='U21'?p.age<=21:age==='30+'?p.age>=30:p.age>=22&&p.age<=29))&&(fullName(p).toLowerCase().includes(search.toLowerCase())||p.country.toLowerCase().includes(search.toLowerCase())));
 if(surface!=='All')rows=rows.filter(({p})=>{const w=p.season?.surfaceWins?.[surface]||p.career.surfaceWins?.[surface]||0,l=p.season?.surfaceLosses?.[surface]||p.career.surfaceLosses?.[surface]||0;return w+l>=3&&w/(w+l)>=.55;});
 const value=(row,key)=>({rank:row.rank,move:(row.p.previousRanking||row.p.ranking)-row.p.ranking,player:fullName(row.p),peak:row.p.career.peakRanking||999,age:row.p.age,rarity:RARITY_ORDER[row.p.rarity]||0,surface:row.p.preferredSurface,race:row.race,defending:status==='Current'?defendingPoints(row.p,universe.year,universe.week):0,points:row.points}[key]);
 rows=[...rows].sort((a,b)=>{const av=value(a,sort.key),bv=value(b,sort.key),cmp=typeof av==='string'?av.localeCompare(bv):av-bv;return sort.direction==='asc'?cmp:-cmp;});
 const onSort=key=>setSort(current=>current.key===key?{key,direction:current.direction==='asc'?'desc':'asc'}:{key,direction:['player','surface'].includes(key)?'asc':'desc'});
 const nations=[...new Set([...universe.players[tour],...universe.retiredPlayers[tour]].map(p=>p.country))].sort(),movers=[...universe.players[tour]].sort((a,b)=>((b.previousRanking||b.ranking)-b.ranking)-((a.previousRanking||a.ranking)-a.ranking)).slice(0,3),endangered=[...universe.players[tour]].map(p=>({p,points:defendingPoints(p,universe.year,universe.week)})).sort((a,b)=>b.points-a.points).slice(0,3);
 const reigns=no1Reigns(universe,tour),totals=new Map();for(const reign of reigns)totals.set(reign.playerId,(totals.get(reign.playerId)||0)+reign.weeks);const mostWeeks=[...totals.entries()].sort((a,b)=>b[1]-a[1])[0],longest=[...reigns].sort((a,b)=>b.weeks-a.weeks)[0];
 return <div className="page"><SectionTitle eyebrow={`${tour} official ranking`}>World rankings</SectionTitle><div className="detail-tabs">{['Current status','Weekly No. 1'].map(x=><button key={x} className={view===x?'active':''} onClick={()=>setView(x)}>{x}</button>)}</div>
 {view==='Current status'&&<><section className="two-column ranking-callouts"><article className="panel"><h3>Top movers</h3>{movers.map(p=><button className="leader-row" key={p.id} onClick={()=>onPlayer(p.id)}><Flag code={p.country}/><strong>{fullName(p)}</strong><Movement player={p}/><b>No. {p.ranking}</b></button>)}</article><article className="panel"><h3>Defending-points danger</h3>{endangered.map(({p,points})=><button className="leader-row" key={p.id} onClick={()=>onPlayer(p.id)}><Flag code={p.country}/><strong>{fullName(p)}</strong><span>next 8 weeks</span><b>{points.toLocaleString()}</b></button>)}</article></section><div className="filter-row"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="Current">Current ranking</option>{snapshots.map(s=><option key={`${s.year}-${s.week}-${s.phase||''}`} value={`${s.year}-${s.week}`}>{universeYearLabel(universe,s.year)} · Week {s.week}</option>)}</select><select value={careerStatus} onChange={e=>setCareerStatus(e.target.value)}><option value="Active">Active players</option><option value="Retired">Retired players</option><option value="All">All players</option></select><select value={nation} onChange={e=>setNation(e.target.value)}><option value="All">All countries</option>{nations.map(n=><option key={n}>{n}</option>)}</select><select value={rarity} onChange={e=>setRarity(e.target.value)}><option value="All">All rarities</option>{['Generational','Legend','Epic','Rare','Uncommon','Common'].map(x=><option key={x}>{x}</option>)}</select><select value={surface} onChange={e=>setSurface(e.target.value)}><option value="All">All surface records</option>{['Hard','Clay','Grass','Indoor'].map(x=><option key={x} value={x}>55%+ on {x}</option>)}</select><select value={age} onChange={e=>setAge(e.target.value)}><option value="All">All ages</option><option value="U21">Under 21</option><option value="22-29">Age 22–29</option><option value="30+">Age 30+</option></select></div><div className="table-wrap"><table className="data-table sortable-table"><thead><tr><SortHeader label="Rank" sortKey="rank" active={sort.key==='rank'} direction={sort.direction} onSort={onSort}/><SortHeader label="Move" sortKey="move" active={sort.key==='move'} direction={sort.direction} onSort={onSort}/><SortHeader label="Player" sortKey="player" active={sort.key==='player'} direction={sort.direction} onSort={onSort}/><SortHeader label="Peak" sortKey="peak" active={sort.key==='peak'} direction={sort.direction} onSort={onSort}/><SortHeader label="Age" sortKey="age" active={sort.key==='age'} direction={sort.direction} onSort={onSort}/><SortHeader label="Rarity" sortKey="rarity" active={sort.key==='rarity'} direction={sort.direction} onSort={onSort}/><SortHeader label="Preferred" sortKey="surface" active={sort.key==='surface'} direction={sort.direction} onSort={onSort}/><SortHeader label="Race" sortKey="race" active={sort.key==='race'} direction={sort.direction} onSort={onSort}/><SortHeader label="Defending 8w" sortKey="defending" active={sort.key==='defending'} direction={sort.direction} onSort={onSort}/><SortHeader label="Points" sortKey="points" active={sort.key==='points'} direction={sort.direction} onSort={onSort}/></tr></thead><tbody>{rows.slice(0,360).map(({p,rank,points,race})=>{const defend=status==='Current'?defendingPoints(p,universe.year,universe.week):0,danger=points>0&&defend/points>=.25;return <tr key={p.id} className={danger?'defending-danger':''}><td className="rank-cell">{rank||'—'}</td><td>{status==='Current'&&p.status!=='retired'?<Movement player={p}/>:<span>—</span>}</td><td><Flag code={p.country}/><PlayerLink player={p} onOpen={onPlayer}/></td><td>{p.career.peakRanking<999?`No. ${p.career.peakRanking}`:'—'}</td><td>{p.age}</td><td><RarityBadge rarity={p.rarity}/></td><td><SurfaceBadge surface={p.preferredSurface}/></td><td>{race.toLocaleString()}</td><td>{status==='Current'?defend.toLocaleString():'—'}</td><td><strong>{points.toLocaleString()}</strong></td></tr>})}</tbody></table></div></>}
 {view==='Weekly No. 1'&&<><section className="two-column no1-records"><article className="panel record-hero"><span>Most weeks at No. 1</span><strong>{mostWeeks?findPlayer(universe,mostWeeks[0])?fullName(findPlayer(universe,mostWeeks[0])):'Unknown':'—'}</strong><b>{mostWeeks?.[1]||0} weeks</b></article><article className="panel record-hero"><span>Longest uninterrupted streak</span><strong>{longest&&findPlayer(universe,longest.playerId)?fullName(findPlayer(universe,longest.playerId)):'—'}</strong><b>{longest?.weeks||0} weeks</b></article></section><section className="panel"><h3>All No. 1 reigns</h3><div className="table-wrap"><table className="data-table"><thead><tr><th>Week starting</th><th>Player</th><th>Weeks</th><th>Max points</th></tr></thead><tbody>{reigns.map((reign,i)=>{const p=findPlayer(universe,reign.playerId);return <tr key={`${reign.playerId}-${reign.startYear}-${reign.startWeek}-${i}`}><td>{universeYearLabel(universe,reign.startYear)} · W{reign.startWeek}</td><td>{p?<><Flag code={p.country}/><PlayerLink player={p} onOpen={onPlayer}/></>:'Unknown'}</td><td>{reign.weeks}w</td><td>{reign.maxPoints.toLocaleString()}</td></tr>})}</tbody></table></div></section></>}
 </div>;
}


function PlayersPage({universe,tour,onPlayer,search}){const [rarity,setRarity]=useState('All'),[surface,setSurface]=useState('All'),[status,setStatus]=useState('Active'),[style,setStyle]=useState('All');const source=status==='Active'?universe.players[tour]:status==='Retired'?universe.retiredPlayers[tour]:[...universe.players[tour],...universe.retiredPlayers[tour]];const players=source.filter(p=>(rarity==='All'||p.rarity===rarity)&&(surface==='All'||p.preferredSurface===surface)&&(style==='All'||p.style===style)&&(fullName(p).toLowerCase().includes(search.toLowerCase())||p.country.toLowerCase().includes(search.toLowerCase())));return <div className="page"><SectionTitle eyebrow={`${tour} player browser`}>Players <span className="title-count">{players.length}</span></SectionTitle><div className="filter-row"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="Active">Active players</option><option value="Retired">Retired players</option><option value="All">All players</option></select><select value={rarity} onChange={e=>setRarity(e.target.value)}><option value="All">All rarities</option>{['Generational','Legend','Epic','Rare','Uncommon','Common'].map(x=><option key={x}>{x}</option>)}</select><select value={surface} onChange={e=>setSurface(e.target.value)}><option value="All">All preferred surfaces</option>{['Hard','Clay','Grass','Indoor'].map(x=><option key={x}>{x}</option>)}</select><select value={style} onChange={e=>setStyle(e.target.value)}><option value="All">All playing styles</option>{[...new Set(source.map(p=>p.style))].map(x=><option key={x}>{x}</option>)}</select></div><div className="player-card-grid">{players.slice(0,220).map(p=><button key={p.id} onClick={()=>onPlayer(p.id)}><header><span>{p.status==='retired'?`Retired${p.retirementYear?` · ${universeYearLabel(universe,p.retirementYear)}`:''}`:`No. ${p.ranking}`}</span><RarityBadge rarity={p.rarity}/></header><h3>{fullName(p)}</h3><p><Flag code={p.country}/> Age {p.age}</p><div className="card-tags"><SurfaceBadge surface={p.preferredSurface}/><span>{p.style}</span></div><div className="mini-stats"><div><strong>{p.currentRating}</strong><span>Rating</span></div><div><strong>{Math.round(p.shape)}</strong><span>Shape</span></div><div><strong>{Math.round(p.fatigue)}</strong><span>Fatigue</span></div></div></button>)}</div></div>}


