 {tab==='News'&&<><div className="filter-row"><select value={category} onChange={e=>setCategory(e.target.value)}><option value="All">All story categories</option>{categories.filter(c=>c!=='All').map(c=><option key={c}>{c}</option>)}</select></div><div className="magazine-layout">{stories.map((story,index)=><article className={story.importance>=5?'lead':''} key={story.id}><span>{story.category} · {universeYearLabel(universe,story.year)}, Week {story.week}</span><h2>{replaceCalendarYears(universe,story.headline)}</h2><p>{replaceCalendarYears(universe,story.body)}</p>{index===0&&<div className="story-rule"/>}</article>)}</div></>}
 {tab==='Year-end Summary'&&summary&&<div className="year-summary-page"><section className="year-summary-hero"><span>Season complete</span><h2>{universeYearLabel(universe,summary.year)}</h2><p>{summary.completedEvents} tournament editions completed.</p></section><div className="two-column">{summary.awards?.map(award=><section className="panel" key={award.tour}><h3>{award.tour} season awards</h3>{[['Year-end No. 1',award.yearEndNo1],['Player of the Year',award.playerOfYear],['Most improved',award.mostImproved],['Newcomer',award.newcomer]].map(([label,row])=>row&&<button className="summary-person" key={label} onClick={()=>onPlayer?.(row.id)}><span>{label}</span><strong>{row.name}</strong></button>)}</section>)}</div><section className="panel"><h3>Grand Slam champions</h3><div className="major-grid">{summary.majorWinners?.map((winner,index)=><article key={`${winner.event}-${index}`}><span>{winner.tour}</span><strong>{winner.event}</strong><p><Flag code={winner.country}/>{winner.winner}</p></article>)}</div></section><div className="two-column">{['ATP','WTA'].map(tour=><section className="panel" key={tour}><h3>{tour} final Top 10</h3>{(summary.rankingTop10?.[tour]||[]).map(row=><button className="leader-row" key={row.id} onClick={()=>onPlayer?.(row.id)}><span>{row.rank}</span><Flag code={row.country}/><strong>{row.name}</strong><b>{row.points.toLocaleString()}</b></button>)}</section>)}</div></div>}
