function AlmanacPage({universe,onPlayer,onTournament}){const years=[...universe.yearSummaries].reverse();return <div className="page"><SectionTitle eyebrow="Season-by-season memory">Almanac</SectionTitle>{years.length?<div className="almanac-years">{years.map(s=><section key={s.year}><header><span>Season</span><h2>{universeYearLabel(universe,s.year)}</h2><p>{s.completedEvents} editions · {s.totalMatches.toLocaleString()} match entries</p></header><div className="award-grid">{s.awards.map(a=><article key={a.tour}><strong>{a.tour}</strong><button className="player-link" onClick={()=>onPlayer(a.yearEndNo1.id)}>{a.yearEndNo1.name}</button><span>Player of Year: {a.playerOfYear.name}</span><small>Most improved: {a.mostImproved?.name}</small></article>)}</div><div className="major-grid">{s.majorWinners.map((m,i)=><button key={`${m.tour}-${m.event}-${i}`} onClick={()=>onTournament(tournamentKey(m.tour,m.event))}><span>{m.tour}</span><strong>{m.event}</strong><p><Flag code={m.country}/>{m.winner}</p></button>)}</div></section>)}</div>:<EmptyState>Complete the first season to open the historical almanac.</EmptyState>}</div>}
function RecordsPage({universe,tour,onPlayer}){
 const [surface,setSurface]=useState('All'),[sortBy,setSortBy]=useState('titles');
 const players=[...universe.players[tour],...universe.retiredPlayers[tour]];
 const metric=p=>{const all=surface==='All';const wins=all?(p.career.wins||0):(p.career.surfaceWins?.[surface]||0),losses=all?(p.career.losses||0):(p.career.surfaceLosses?.[surface]||0),titles=all?(p.career.titles||0):(p.career.surfaceTitles?.[surface]||0),majors=(p.career.titleLog||[]).filter(row=>row.level==='Grand Slam'&&(all||row.surface===surface)).length;return {p,titles,majors,wins,losses,winPct:wins+losses?wins/(wins+losses)*100:0};};
 const key={titles:'titles',majors:'majors',wins:'wins',winPct:'winPct'}[sortBy];const rows=players.map(metric).sort((a,b)=>b[key]-a[key]||b.majors-a.majors||b.titles-a.titles).slice(0,20);
 return <div className="page"><SectionTitle eyebrow={`${tour} all-time leaderboards`}>Records</SectionTitle><div className="filter-row"><select value={surface} onChange={e=>setSurface(e.target.value)}><option value="All">All surfaces</option>{['Hard','Clay','Grass','Indoor'].map(value=><option key={value}>{value}</option>)}</select><select value={sortBy} onChange={e=>setSortBy(e.target.value)}><option value="titles">Sort by titles</option><option value="majors">Sort by Grand Slams</option><option value="wins">Sort by games won</option><option value="winPct">Sort by win percentage</option></select></div><div className="table-wrap"><table className="data-table records-table"><thead><tr><th>#</th><th>Player</th><th>Rarity</th><th>Titles</th><th>GS</th><th>Games won</th><th>Win %</th></tr></thead><tbody>{rows.map((row,index)=><tr key={row.p.id}><td>{index+1}</td><td><Flag code={row.p.country}/><PlayerLink player={row.p} onOpen={onPlayer}/></td><td><RarityBadge rarity={row.p.rarity}/></td><td>{row.titles}</td><td>{row.majors}</td><td>{row.wins}</td><td>{row.winPct.toFixed(1)}%</td></tr>)}</tbody></table></div></div>;
}

function WorldPage({universe,slot,onSave,onExit,onToggle}){const stats=[['ATP singles',universe.players.ATP.length,SINGLES_CAP],['WTA singles',universe.players.WTA.length,SINGLES_CAP],['ATP doubles',universe.doublesPlayers.ATP.length,DOUBLES_CAP],['WTA doubles',universe.doublesPlayers.WTA.length,DOUBLES_CAP],['ATP juniors',universe.juniors.ATP.length,JUNIOR_TARGET],['WTA juniors',universe.juniors.WTA.length,JUNIOR_TARGET]];return <div className="page"><SectionTitle eyebrow={`Save slot ${slot}`}>World settings</SectionTitle><section className="panel world-rules"><h3>Population integrity</h3><p>Every January restores exactly 360 ATP and 360 WTA singles players, caps dedicated doubles at 160, and replenishes juniors to 120.</p><div className="population-audit">{stats.map(([label,value,target])=><div key={label}><span>{label}</span><strong className={value===target?'ok':'bad'}>{value} / {target}</strong></div>)}</div></section><section className="panel"><h3>Simulation options</h3>{[['injuries','Injuries and protected rankings'],['juniorProEntries','Junior professional exemptions']].map(([key,label])=><label className="setting-row" key={key}><span>{label}</span><input type="checkbox" checked={!!universe.settings[key]} onChange={()=>onToggle(key)}/></label>)}</section><section className="panel world-actions"><button onClick={onSave}>Save now</button><button className="secondary" onClick={onExit}>Save and return to slots</button></section></div>}

function ChronicleApp(){
 const [slots,setSlots]=useState([]),[slot,setSlot]=useState(null),[universe,setUniverse]=useState(null),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[tour,setTour]=useState('ATP'),[search,setSearch]=useState('');const {route,go,back}=useHashRoute();
 const refreshSlots=async()=>{const rows=await listSlots();setSlots(rows.map(r=>r.metadata||r))};useEffect(()=>{refreshSlots()},[]);const persist=async next=>{if(slot&&next)await saveSlot(slot,next)};
 const createWorld=async(targetSlot,name)=>{setBusy(true);setNotice('Building complete tennis universe…');try{const next=ensureUniverseData(createUniverse({seed:Date.now()+targetSlot,startYear:2026,name}));const rng=new RNG(next.rngSeed);rebuildDoublesTeams(next,'ATP',rng);rebuildDoublesTeams(next,'WTA',rng);next.rngSeed=rng.seed;await saveSlot(targetSlot,next);setSlot(targetSlot);setUniverse(next);go('home');await refreshSlots()}finally{setBusy(false)}};
 const loadWorld=async targetSlot=>{setBusy(true);try{const loaded=await loadSlot(targetSlot);if(loaded){ensureUniverseData(loaded);if(!loaded.doublesTeams.ATP.length||!loaded.doublesTeams.WTA.length){const rng=new RNG(loaded.rngSeed);rebuildDoublesTeams(loaded,'ATP',rng);rebuildDoublesTeams(loaded,'WTA',rng);loaded.rngSeed=rng.seed}setSlot(targetSlot);setUniverse(loaded);go('home')}}finally{setBusy(false)}};
 const removeWorld=async targetSlot=>{if(!window.confirm(`Delete save slot ${targetSlot} permanently?`))return;await deleteSlot(targetSlot);await refreshSlots()};
 const mutate=async(label,fn)=>{if(!universe||busy)return;setBusy(true);setNotice(label);try{const next=clone(universe);ensureUniverseData(next);fn(next);next.meta.updatedAt=new Date().toISOString();setUniverse(next);await persist(next);setNotice('Autosaved.')}catch(e){console.error(e);setNotice(`Simulation error: ${e.message}`);throw e}finally{setBusy(false)}};
 const saveNow=async()=>{if(!universe)return;setBusy(true);try{await persist(universe);setNotice('Save complete.');await refreshSlots()}finally{setBusy(false)}};const exitToSlots=async()=>{await saveNow();setUniverse(null);setSlot(null);await refreshSlots()};
 if(!universe)return <SaveSlots slots={slots} onCreate={createWorld} onLoad={loadWorld} onDelete={removeWorld} busy={busy}/>;
 const onPlayer=id=>go('player',id),onTournament=key=>go('tournament',key),onMatch=(editionId,matchId)=>go('match',editionId,matchId),onRivalry=(a,b)=>go('rivalry',a,b);
 const toggleFollow=id=>mutate('Updating followed players…',n=>{n.followedPlayerIds??=[];n.followedPlayerIds=n.followedPlayerIds.includes(id)?n.followedPlayerIds.filter(x=>x!==id):[...n.followedPlayerIds,id]});let page;
 if(route.page==='player')page=<PlayerPage universe={universe} playerId={route.parts[0]} onBack={()=>back('players')} onPlayer={onPlayer} onTournament={onTournament} onRivalry={onRivalry} isFollowed={(universe.followedPlayerIds||[]).includes(route.parts[0])} onToggleFollow={()=>toggleFollow(route.parts[0])}/>;
 else if(route.page==='tournament'){const [t,...nameParts]=(route.parts[0]||'').split('|');const name=nameParts.join('|');page=<TournamentDetailPage universe={universe} tour={t||tour} name={name} onBack={()=>back('tournaments')} onPlayer={onPlayer} onMatch={onMatch} onSimulate={week=>mutate(`Simulating to week ${week}…`,n=>advanceWeeks(n,Math.max(0,week-n.week+1)))}/>}
 else if(route.page==='rivalry')page=<RivalryPage universe={universe} playerAId={route.parts[0]} playerBId={route.parts[1]} onBack={()=>back('records')} onPlayer={onPlayer} onMatch={onMatch}/>;
 else if(route.page==='match')page=<MatchPage universe={universe} editionId={route.parts[0]} matchId={route.parts[1]} onBack={()=>back('tournaments')} onPlayer={onPlayer}/>;
 else if(route.page==='home')page=<HomePage universe={universe} onPlayer={onPlayer} onTournament={onTournament}/>;
 else if(route.page==='calendar')page=<CalendarPage universe={universe} tour={tour} onTournament={onTournament}/>;
 else if(route.page==='tournaments')page=<TournamentsPage universe={universe} tour={tour} onTournament={onTournament}/>;
 else if(route.page==='rankings')page=<RankingsPage universe={universe} tour={tour} onPlayer={onPlayer} search={search}/>;
 else if(route.page==='players')page=<PlayersPage universe={universe} tour={tour} onPlayer={onPlayer} search={search}/>;
 else if(route.page==='doubles')page=<DoublesPage universe={universe} tour={tour} onPlayer={onPlayer} onTournament={onTournament}/>;
 else if(route.page==='juniors')page=<JuniorsPage universe={universe} tour={tour} onPlayer={onPlayer} onTournament={onTournament} search={search}/>;
 else if(route.page==='national-teams')page=<NationalTeamsPage universe={universe} tour={tour} onPlayer={onPlayer}/>;
 else if(route.page==='magazine')page=<MagazinePage universe={universe} onPlayer={onPlayer}/>;
 else if(route.page==='almanac')page=<AlmanacPage universe={universe} onPlayer={onPlayer} onTournament={onTournament}/>;
 else if(route.page==='records')page=<RecordsPage universe={universe} tour={tour} onPlayer={onPlayer}/>;
 else page=<WorldPage universe={universe} slot={slot} onSave={saveNow} onExit={exitToSlots} onToggle={key=>mutate('Updating settings…',n=>{n.settings[key]=!n.settings[key]})}/>;
 const finishSeason=async()=>{await mutate('Completing the season…',next=>simulateToEndOfYear(next));go('magazine');};
 const moveNextSeason=async()=>{await mutate(`Opening ${universeYearLabel(universe,universe.year+1)}…`,next=>openNextSeason(next));go('magazine');};
 const activeNav=route.page==='player'?'players':route.page==='rivalry'?'records':route.page==='tournament'||route.page==='match'?'tournaments':route.page;
 return <div className="app-shell"><header className="top-shell"><div className="brand-row"><button className="brand" onClick={()=>go('home')}><span>TWC</span><div><strong>Tennis World Chronicle</strong><small>{universe.name}</small></div></button><div className="season-chip"><span>{universeYearLabel(universe)}</span><strong>Week {universe.week}</strong></div><div className="tour-toggle"><button className={tour==='ATP'?'active':''} onClick={()=>setTour('ATP')}>ATP</button><button className={tour==='WTA'?'active':''} onClick={()=>setTour('WTA')}>WTA</button></div><label className="global-search"><span>⌕</span><input placeholder="Search players or country" value={search} onChange={e=>setSearch(e.target.value)}/></label><button className="save-icon" onClick={saveNow}>Save</button></div><nav className="main-nav">{NAV.map(([label,key])=><button key={key} className={activeNav===key?'active':''} onClick={()=>go(key)}>{label}</button>)}</nav><div className="simulation-bar"><div><span className={`live-dot ${busy?'busy':''}`}/><strong>{busy?notice:universe.seasonEnded?`${universeYearLabel(universe)} complete`:'Simulation controls'}</strong><small>{!busy&&notice}</small></div><div className="sim-buttons">{universe.seasonEnded?<button className="next-season-button" disabled={busy} onClick={moveNextSeason}>Move to {universeYearLabel(universe,universe.year+1)}</button>:<><button disabled={busy} onClick={()=>mutate('Simulating one week…',next=>advanceWeeks(next,1))}>+1 Week</button><button disabled={busy} onClick={()=>mutate('Simulating four weeks…',next=>advanceWeeks(next,4))}>+4 Weeks</button><button disabled={busy} onClick={finishSeason}>End of Year</button></>}</div></div></header><main className="content-shell">{page}</main></div>
}
export default function App(){return <ErrorBoundary><ChronicleApp/></ErrorBoundary>}
